result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "respserver.py", "content": """"Minimal RESP2 Redis-protocol subset server (Python stdlib only).

Supports: PING, SET k v, GET k, DEL k, INCR k, EXISTS k.

Requests are RESP arrays of bulk strings, e.g.
    *2\r\n$3\r\nGET\r\n$1\r\nk\r\n

Replies use RESP2 simple strings (+), errors (-), integers (:),
bulk strings ($), and null bulk ($-1).
"""

import socket
import threading


class RESPError(Exception):
    """Raised when the incoming byte stream is not valid RESP."""


def _read_crlf(buf, idx):
    """Return (line_bytes_without_crlf, new_idx) starting at idx."""
    end = buf.find(b"\r\n", idx)
    if end == -1:
        return None, idx  # incomplete
    return buf[idx:end], end + 2


def try_parse_command(buf):
    """Try to parse exactly one RESP array-of-bulk-strings command from buf.

    Returns (args_list, rest_bytes) on success, (None, buf) if more data
    is needed. Raises RESPError on malformed input.
    """
    line, idx = _read_crlf(buf, 0)
    if line is None:
        return None, buf
    if not line.startswith(b"*"):
        raise RESPError("expected array header")
    try:
        nargs = int(line[1:])
    except ValueError:
        raise RESPError("invalid array length")
    if nargs < 0:
        raise RESPError("invalid array length")

    args = []
    for _ in range(nargs):
        line, idx = _read_crlf(buf, idx)
        if line is None:
            return None, buf
        if not line.startswith(b"$"):
            raise RESPError("expected bulk string header")
        try:
            blen = int(line[1:])
        except ValueError:
            raise RESPError("invalid bulk length")
        if blen < 0:
            raise RESPError("invalid bulk length")
        # need blen payload bytes + CRLF terminator
        if len(buf) < idx + blen + 2:
            return None, buf
        args.append(bytes(buf[idx : idx + blen]))
        if buf[idx + blen : idx + blen + 2] != b"\r\n":
            raise RESPError("expected CRLF after bulk data")
        idx += blen + 2

    return args, bytes(buf[idx:])


class Store:
    def __init__(self):
        self._data = {}
        self._lock = threading.Lock()

    def apply(self, args):
        """Execute a decoded command; return the raw RESP reply bytes."""
        if not args:
            return b"-ERR empty command\r\n"
        cmd = args[0].decode("latin-1").upper()
        argc = len(args) - 1

        if cmd == "PING" and argc == 0:
            return b"+PONG\r\n"

        if cmd in ("SET", "GET", "DEL", "INCR", "EXISTS") and argc < 1:
            return ("-ERR wrong number of arguments for '%s' command\r\n"
                    % cmd.lower()).encode()

        if cmd == "SET":
            if argc != 2:
                return b"-ERR wrong number of arguments for 'set' command\r\n"
            key, val = args[1], args[2]
            with self._lock:
                self._data[key] = val
            return b"+OK\r\n"

        if cmd == "GET":
            if argc != 1:
                return b"-ERR wrong number of arguments for 'get' command\r\n"
            key = args[1]
            with self._lock:
                val = self._data.get(key)
            if val is None:
                return b"$-1\r\n"
            return b"$%d\r\n%s\r\n" % (len(val), val)

        if cmd == "DEL":
            if argc != 1:
                return b"-ERR wrong number of arguments for 'del' command\r\n"
            key = args[1]
            with self._lock:
                existed = self._data.pop(key, None) is not None
            return b":1\r\n" if existed else b":0\r\n"

        if cmd == "EXISTS":
            if argc != 1:
                return b"-ERR wrong number of arguments for 'exists' command\r\n"
            key = args[1]
            with self._lock:
                existed = key in self._data
            return b":1\r\n" if existed else b":0\r\n"

        if cmd == "INCR":
            if argc != 1:
                return b"-ERR wrong number of arguments for 'incr' command\r\n"
            key = args[1]
            with self._lock:
                cur = self._data.get(key)
                if cur is None:
                    new = 1
                    self._data[key] = b"1"
                else:
                    try:
                        n = int(cur)
                    except ValueError:
                        return b"-ERR value is not an integer\r\n"
                    new = n + 1
                    self._data[key] = str(new).encode()
            return b":%d\r\n" % new

        return ("-ERR unknown command '%s'\r\n" % cmd.lower()).encode()


def handle_connection(sock, store):
    buf = b""
    try:
        while True:
            while True:
                try:
                    args, buf = try_parse_command(buf)
                except RESPError as exc:
                    sock.sendall(("-ERR protocol error: %s\r\n" % exc).encode())
                    return
                if args is None:
                    break
                reply = store.apply(args)
                sock.sendall(reply)

            chunk = sock.recv(65536)
            if not chunk:
                break
            buf += chunk
    except OSError:
        pass  # client hung up / socket torn down
    finally:
        try:
            sock.close()
        except OSError:
            pass


class RESPSubsetServer:
    """TCP server bound to an ephemeral localhost port."""

    def __init__(self):
        self.store = Store()
        self._sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        self._sock.setsockopt(socket.SOL_SOCKET, socket.SO_REUSEADDR, 1)
        self._sock.bind(("127.0.0.1", 0))
        self.port = self._sock.getsockname()[1]
        self._sock.listen(128)
        self._running = False
        self._threads = []

    def serve_forever(self):
        self._running = True
        while self._running:
            try:
                client, _ = self._sock.accept()
            except OSError:
                break  # socket closed by shutdown()
            t = threading.Thread(
                target=handle_connection, args=(client, self.store), daemon=True
            )
            t.start()
            self._threads.append(t)

    def start_background(self):
        t = threading.Thread(target=self.serve_forever, daemon=True)
        t.start()
        return t

    def shutdown(self):
        self._running = False
        try:
            self._sock.close()
        except OSError:
            pass


if __name__ == "__main__":
    import sys

    srv = RESPSubsetServer()
    print("listening on 127.0.0.1:%d" % srv.port, flush=True)
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        srv.shutdown()
